let modo = 'completo';
try { const m = $('Modo: Sentinela').first().json.modo; if (m) modo = m; } catch (e) {}
try { const m = $('Modo: Completo').first().json.modo; if (m) modo = m; } catch (e) {}
try { const m = $('Modo: Manual').first().json.modo; if (m) modo = m; } catch (e) {}
const ativo = v => v === true || v === 'true' || v === 1 || v === '1';
return $input.all()
  .filter(i => i.json && i.json.cliente && ativo(i.json.ativo))
  .map(i => ({ json: { ...i.json, modo } }));

const r = $input.first().json;
const hoje = new Date();
function d(offsetDias) {
  const x = new Date(hoje.getTime() - offsetDias * 86400000);
  return x.toISOString().slice(0, 10);
}
const slug = String(r.cliente || 'cliente').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const carimbo = hoje.toISOString().slice(0, 10).replace(/-/g, '');
const modo = r.modo || 'completo';
return [{ json: {
  cliente: r.cliente,
  modo,
  ciclo_id: slug + '-' + carimbo + (modo === 'sentinela' ? '-S' : ''),
  site_url: r.site_url || '',
  contexto_negocio: r.contexto_negocio || '',
  vertical: r.vertical || '',
  tier: r.tier || 'essential',
  ga4_property_id: String(r.ga4_property_id || '').replace(/[^0-9]/g, ''),
  clarity_api_token: r.clarity_api_token || '',
  jira_base_url: String(r.jira_base_url || '').replace(/\/$/, ''),
  jira_project_key: r.jira_project_key || '',
  jira_issue_type: r.jira_issue_type || 'Task',
  email_analista: r.email_analista || 'tsoares@cadastra.com',
  valor_por_conversao: Number(r.valor_por_conversao) || 0,
  moeda: r.moeda || 'BRL',
  periodo_inicio: d(28), periodo_fim: d(1),
  periodo_prev_inicio: d(56), periodo_prev_fim: d(29)
} }];

function safe(nome) { try { const j = $(nome).first().json; return j || null; } catch (e) { return null; } }
const ga4Tot = safe('GA4 – Totais do Período');
const ga4Fun = safe('GA4 – Eventos de Funil');
const ga4Can = safe('GA4 – Canais & Devices');
const clarity = safe('Clarity – Comportamento');
const jira = safe('Jira – Backlog Existente');
const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const pct = (a, b) => (b > 0 ? ((a - b) / b) * 100 : null);
const round1 = v => (v === null || v === undefined ? null : Math.round(v * 10) / 10);

let kpis = { sessoes: null, usuarios: null, conversoes: null, receita: null, taxa_conversao: null, sessoes_ant: null, conversoes_ant: null, receita_ant: null, taxa_ant: null, sessoes_delta: null, conversoes_delta: null, receita_delta: null, taxa_delta: null };
let ga4ok = false;
if (ga4Tot && Array.isArray(ga4Tot.rows)) {
  ga4ok = true;
  for (const row of ga4Tot.rows) {
    const dims = (row.dimensionValues || []).map(x => x.value);
    const faixa = dims[dims.length - 1] || 'atual';
    const m = (row.metricValues || []).map(x => num(x.value));
    if (faixa === 'atual' || faixa === 'date_range_0') { kpis.sessoes = m[0]; kpis.usuarios = m[1]; kpis.conversoes = m[2]; kpis.receita = m[3]; }
    else { kpis.sessoes_ant = m[0]; kpis.conversoes_ant = m[2]; kpis.receita_ant = m[3]; }
  }
  kpis.taxa_conversao = kpis.sessoes > 0 ? round1((kpis.conversoes / kpis.sessoes) * 1000) / 10 : null;
  kpis.taxa_ant = kpis.sessoes_ant > 0 ? round1((kpis.conversoes_ant / kpis.sessoes_ant) * 1000) / 10 : null;
  kpis.sessoes_delta = round1(pct(kpis.sessoes, kpis.sessoes_ant));
  kpis.conversoes_delta = round1(pct(kpis.conversoes, kpis.conversoes_ant));
  kpis.receita_delta = round1(pct(kpis.receita, kpis.receita_ant));
  kpis.taxa_delta = round1(pct(kpis.taxa_conversao, kpis.taxa_ant));
}

const eventos = {};
if (ga4Fun && Array.isArray(ga4Fun.rows)) {
  for (const row of ga4Fun.rows) {
    const dims = (row.dimensionValues || []).map(x => x.value);
    const nome = dims[0];
    const faixa = dims[dims.length - 1] || 'atual';
    const m = (row.metricValues || []).map(x => num(x.value));
    eventos[nome] = eventos[nome] || { atual: 0, anterior: 0, usuarios_atual: 0 };
    if (faixa === 'atual' || faixa === 'date_range_0') { eventos[nome].atual = m[0]; eventos[nome].usuarios_atual = m[1]; }
    else { eventos[nome].anterior = m[0]; }
  }
}
const funil_eventos = Object.entries(eventos).map(([evento, v]) => ({ evento, atual: v.atual, anterior: v.anterior, delta_pct: round1(pct(v.atual, v.anterior)), usuarios: v.usuarios_atual }));
const ev = n => eventos[n] ? eventos[n].atual : 0;
const taxas_funil = {};
if (kpis.sessoes > 0 && ev('add_to_cart') > 0) taxas_funil.sessao_para_carrinho_pct = round1((ev('add_to_cart') / kpis.sessoes) * 100);
if (ev('add_to_cart') > 0 && ev('begin_checkout') > 0) taxas_funil.carrinho_para_checkout_pct = round1((ev('begin_checkout') / ev('add_to_cart')) * 100);
if (ev('begin_checkout') > 0 && ev('purchase') > 0) taxas_funil.checkout_para_compra_pct = round1((ev('purchase') / ev('begin_checkout')) * 100);
if (kpis.sessoes > 0 && ev('generate_lead') > 0) taxas_funil.sessao_para_lead_pct = round1((ev('generate_lead') / kpis.sessoes) * 100);
if (ev('form_start') > 0 && ev('form_submit') > 0) taxas_funil.form_conclusao_pct = round1((ev('form_submit') / ev('form_start')) * 100);

let canais = [];
const porDevice = {};
if (ga4Can && Array.isArray(ga4Can.rows)) {
  canais = ga4Can.rows.slice(0, 12).map(row => {
    const dims = (row.dimensionValues || []).map(x => x.value);
    const m = (row.metricValues || []).map(x => num(x.value));
    const item = { canal: dims[0], device: dims[1], sessoes: m[0], conversoes: m[1], receita: m[2], taxa_pct: m[0] > 0 ? round1((m[1] / m[0]) * 100) : 0 };
    porDevice[item.device] = porDevice[item.device] || { sessoes: 0, conversoes: 0 };
    porDevice[item.device].sessoes += m[0]; porDevice[item.device].conversoes += m[1];
    return item;
  });
}
const devices = Object.entries(porDevice).map(([device, v]) => ({ device, sessoes: v.sessoes, conversoes: v.conversoes, taxa_pct: v.sessoes > 0 ? round1((v.conversoes / v.sessoes) * 100) : 0 }));

let clarity_metricas = [];
let clarityok = false;
const clarityArr = Array.isArray(clarity) ? clarity : (clarity && Array.isArray(clarity.data) ? clarity.data : null);
if (clarityArr) {
  clarityok = true;
  clarity_metricas = clarityArr.filter(m => m && m.metricName).map(m => ({ metrica: m.metricName, dados: (m.information || []).slice(0, 3) }));
}

let backlog_jira = [];
let jiraok = false;
if (jira && Array.isArray(jira.issues)) {
  jiraok = true;
  backlog_jira = jira.issues.map(i => ({ key: i.key, resumo: i.fields && i.fields.summary, status: i.fields && i.fields.status && i.fields.status.name }));
}

return [{ json: {
  kpis, funil_eventos, taxas_funil, canais, devices, clarity_metricas, backlog_jira,
  purchase_atual: ev('purchase'),
  purchase_anterior: eventos['purchase'] ? eventos['purchase'].anterior : 0,
  coleta: { ga4: ga4ok, clarity: clarityok, jira: jiraok }
} }];

const P = $('Preparar Cliente').first().json;
const M = $('Normalizar Métricas').first().json;
const kpis = M.kpis;
const round1 = v => (v === null || v === undefined ? null : Math.round(v * 10) / 10);
const pct = (a, b) => (b > 0 ? ((a - b) / b) * 100 : null);

const anomalias = [];
function anexa(severidade, metrica, variacao, mensagem) { anomalias.push({ severidade, metrica, variacao_pct: round1(variacao), mensagem }); }
if (M.coleta.ga4 && kpis.sessoes_ant > 100) {
  if (kpis.sessoes_delta !== null && kpis.sessoes_delta <= -30) anexa('alta', 'sessoes', kpis.sessoes_delta, 'Queda de ' + Math.abs(kpis.sessoes_delta) + '% nas sessões vs período anterior (' + kpis.sessoes_ant + ' para ' + kpis.sessoes + ').');
  if (kpis.conversoes_delta !== null && kpis.conversoes_delta <= -25) anexa('critica', 'conversoes', kpis.conversoes_delta, 'Queda de ' + Math.abs(kpis.conversoes_delta) + '% nas conversões vs período anterior (' + kpis.conversoes_ant + ' para ' + kpis.conversoes + ').');
  if (kpis.receita_ant > 0 && kpis.receita_delta !== null && kpis.receita_delta <= -25) anexa('critica', 'receita', kpis.receita_delta, 'Queda de ' + Math.abs(kpis.receita_delta) + '% na receita vs período anterior.');
  if (kpis.taxa_delta !== null && kpis.taxa_delta <= -20 && kpis.sessoes_delta !== null && kpis.sessoes_delta > -15) anexa('alta', 'taxa_conversao', kpis.taxa_delta, 'Taxa de conversão caiu ' + Math.abs(kpis.taxa_delta) + '% com tráfego estável — investigar UX/checkout.');
  if (M.purchase_anterior > 20) {
    const dv = pct(M.purchase_atual, M.purchase_anterior);
    if (dv !== null && dv <= -40 && kpis.sessoes_delta !== null && kpis.sessoes_delta > -15) anexa('critica', 'purchase', dv, 'Eventos de compra caíram ' + Math.abs(Math.round(dv)) + '% com tráfego estável — possível checkout quebrado.');
  }
}

const sevRank = { critica: 3, alta: 2, media: 1 };
anomalias.sort((a, b) => (sevRank[b.severidade] || 0) - (sevRank[a.severidade] || 0));
const pior = anomalias[0] || null;
const alerta_row = pior ? {
  cliente: P.cliente, tipo: 'protecao_receita', severidade: pior.severidade, metrica: anomalias.map(a => a.metrica).join(','),
  variacao_pct: pior.variacao_pct || 0, mensagem: anomalias.map(a => a.mensagem).join(' | '), ciclo_id: P.ciclo_id, criado_em: new Date().toISOString()
} : null;
const alerta_email_html = pior ? (
  '<div style="font-family:Arial,sans-serif;max-width:640px">' +
  '<h2 style="color:#ef4444">🚨 CXO Next — Proteção de receita: ' + P.cliente + '</h2>' +
  '<p>A ingestão detectou anomalias antes do cliente perceber. Período analisado: <b>' + P.periodo_inicio + ' a ' + P.periodo_fim + '</b> vs anterior.</p>' +
  '<ul>' + anomalias.map(a => '<li><b>[' + a.severidade.toUpperCase() + ']</b> ' + a.mensagem + '</li>').join('') + '</ul>' +
  '<p style="color:#6b7280;font-size:12px">Verifique tagueamento, checkout e mudanças recentes no site antes de acionar o cliente. Registro gravado em cro_alertas.</p></div>'
) : '';

return [{ json: {
  ciclo_id: P.ciclo_id, cliente: P.cliente, modo: P.modo,
  periodo: P.periodo_inicio + ' a ' + P.periodo_fim,
  registro: { site_url: P.site_url, contexto_negocio: P.contexto_negocio, vertical: P.vertical, tier: P.tier, jira_base_url: P.jira_base_url, jira_project_key: P.jira_project_key, jira_issue_type: P.jira_issue_type, email_analista: P.email_analista, valor_por_conversao: P.valor_por_conversao, moeda: P.moeda },
  kpis: M.kpis, funil_eventos: M.funil_eventos, taxas_funil: M.taxas_funil, canais: M.canais, devices: M.devices,
  clarity_metricas: M.clarity_metricas, backlog_jira: M.backlog_jira, anomalias,
  tem_anomalia: anomalias.length > 0, alerta_row, alerta_email_html,
  coleta: M.coleta
} }];

// Agente Bibliotecário (RAG): seleciona conhecimento relevante para o ciclo e registra a trilha.
const ING = $('Agente de Ingestão (Normalizar)').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.conteudo);
const ativos = rows.filter(r => r.ativo === true || r.ativo === 'true' || r.ativo === 1 || r.ativo === undefined);

const reg = ING.registro || {};
const taxas = ING.taxas_funil || {};
const termos = [];
const push = t => { if (t) termos.push(String(t).toLowerCase()); };
push(reg.vertical); push(ING.modo);
(ING.anomalias || []).forEach(a => push(a.metrica));
if (taxas.carrinho_para_checkout_pct !== undefined && taxas.carrinho_para_checkout_pct < 55) { push('checkout'); push('carrinho'); }
if (taxas.checkout_para_compra_pct !== undefined && taxas.checkout_para_compra_pct < 40) { push('checkout'); push('abandono'); }
if (taxas.sessao_para_carrinho_pct !== undefined) push('e-commerce');
if (taxas.form_conclusao_pct !== undefined) { push('formularios'); push('lead'); }
(ING.clarity_metricas || []).forEach(m => { if (/rage/i.test(m.metrica || '')) push('rage-clicks'); });

// núcleo PSM sempre presente (metodologia base da fábrica)
const NUCLEO = ['Fórmula de hipótese', 'KPI principal, secundários e NEGATIVOS', 'relevância estatística', 'Calculadora de potencial', 'Priorização de hipóteses', 'QA de métricas'];
const ehNucleo = r => NUCLEO.some(n => (r.titulo || '').toLowerCase().includes(n.toLowerCase()));

function score(r) {
  let s = 0;
  const hay = ((r.titulo || '') + ' ' + (r.tags || '') + ' ' + (r.etapa_funil || '') + ' ' + (r.vertical || '')).toLowerCase();
  termos.forEach(t => { if (t && hay.includes(t)) s += 1; });
  if ((r.vertical || 'todas') !== 'todas' && reg.vertical && (r.vertical || '').toLowerCase() === String(reg.vertical).toLowerCase()) s += 2;
  if (r.origem === 'aprendizado_ciclo' || r.origem === 'resultado_teste') {
    s += 1;
    if ((r.tags || '').toLowerCase().includes(String(ING.cliente || '').toLowerCase())) s += 4; // aprendizado do próprio cliente
  }
  return s;
}

const nucleo = ativos.filter(ehNucleo);
const resto = ativos.filter(r => !ehNucleo(r)).map(r => ({ r, s: score(r) })).sort((a, b) => b.s - a.s);
const escolhidos = nucleo.concat(resto.slice(0, 6).map(x => x.r)).slice(0, 12);

const corta = (t, n) => { t = String(t || ''); return t.length > n ? t.slice(0, n) + '…' : t; };
const conhecimento_texto = escolhidos.map((r, i) =>
  '[C' + (i + 1) + '] (' + (r.origem || 'ref') + ') ' + r.titulo + '\n' + corta(r.conteudo, 700)
).join('\n\n');

const trilha_conhecimento = escolhidos.map((r, i) => ({ ref: 'C' + (i + 1), id: r.id !== undefined ? r.id : null, titulo: r.titulo, origem: r.origem || '' }));

return [{ json: {
  conhecimento_texto: conhecimento_texto || 'Base de conhecimento vazia — rode o seed do workflow CXO Next — Conhecimento & Feedback.',
  trilha_conhecimento,
  conhecimento_qtd: escolhidos.length,
  tem_anomalia: ING.tem_anomalia
} }];

// Agente de Memória (loop de feedback): o que já foi aprovado/testado para este cliente.
const ING = $('Agente de Ingestão (Normalizar)').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.cliente === ING.cliente);

const comResultado = rows.filter(r => r.resultado && String(r.resultado).trim() !== '');
const pendentes = rows.filter(r => !r.resultado || String(r.resultado).trim() === '');

const linha = r => '- ' + (r.hipotese_id || '?') + ' · ' + (r.titulo || 'sem título')
  + (r.jira_issue_key ? ' (' + r.jira_issue_key + ')' : '')
  + (r.resultado ? ' → RESULTADO: ' + r.resultado : ' → status: ' + (r.status_implementacao || 'aprovada') + ' (sem resultado ainda)');

let memoria_resumo = '';
if (!rows.length) {
  memoria_resumo = 'Primeiro ciclo com memória para este cliente — nenhuma hipótese anterior registrada.';
} else {
  memoria_resumo = 'HIPÓTESES JÁ APROVADAS PARA ESTE CLIENTE (' + rows.length + '):\n'
    + rows.slice(0, 15).map(linha).join('\n')
    + '\n\nREGRAS: (1) NÃO repetir hipóteses já aprovadas — propor ângulos complementares ou novas frentes. '
    + '(2) Resultados POSITIVOS indicam padrões que funcionam com este público — considere estendê-los a outras etapas. '
    + '(3) Resultados NEGATIVOS/INCONCLUSIVOS são aprendizado — não insistir na mesma tese sem nova evidência.';
}

const memoria_itens = rows.slice(0, 15).map(r => ({
  hipotese_id: r.hipotese_id || '', titulo: r.titulo || '', jira_issue_key: r.jira_issue_key || '',
  status: r.status_implementacao || '', resultado: r.resultado || ''
}));

return [{ json: {
  memoria_resumo,
  memoria_itens,
  memoria_qtd: rows.length,
  memoria_com_resultado: comResultado.length,
  memoria_pendentes: pendentes.length,
  tem_anomalia: ING.tem_anomalia
} }];

