function saida(nome) { try { const j = $(nome).first().json; return j && j.output !== undefined ? j.output : null; } catch (e) { return null; } }
const base = $('Agente de Ingestão (Normalizar)').first().json;
const achadosOut = saida('Agente Heurístico UX') || {};
const diagOut = saida('Agente Diagnóstico de Funil') || {};
const iceOut = saida('Agente Priorização ICE') || {};
const sinteseOut = saida('Agente de Síntese');
const autoOut = saida('Agente Autocrítica (Revisor)') || {};

const achados = achadosOut.achados || [];
const gargalos = diagOut.gargalos || [];
const hipoteses = iceOut.hipoteses || [];
const sintese_md = typeof sinteseOut === 'string' ? sinteseOut : (sinteseOut ? JSON.stringify(sinteseOut) : '');
const autocritica = { score: Number(autoOut.score) || 0, recomendacao: autoOut.recomendacao || 'revisar', problemas: autoOut.problemas || [], pontos_fortes: autoOut.pontos_fortes || [] };

const pipelineOk = achados.length > 0 || gargalos.length > 0 || hipoteses.length > 0;
let status = 'erro_pipeline';
if (pipelineOk) status = autocritica.score >= 7 ? 'aguardando_gate' : 'requer_revisao';

const soma = (arr, sel) => arr.reduce((acc, g) => acc + (Number(sel(g)) || 0), 0);
const oportunidade_total_min = Math.round(soma(gargalos, g => (g.oportunidade_reais_mes || {}).min));
const oportunidade_total_max = Math.round(soma(gargalos, g => (g.oportunidade_reais_mes || {}).max));

const dados = {
  ciclo_id: base.ciclo_id, cliente: base.cliente, periodo: base.periodo, registro: base.registro,
  kpis: base.kpis, taxas_funil: base.taxas_funil, funil_eventos: base.funil_eventos, canais: base.canais, devices: base.devices,
  clarity_metricas: base.clarity_metricas, backlog_jira: base.backlog_jira, anomalias: base.anomalias, coleta: base.coleta,
  achados, gargalos, hipoteses, autocritica, sintese_md,
  resumo_diagnostico: diagOut.resumo_diagnostico || '',
  trilha_conhecimento: (function(){ try { return $('Agente Bibliotecário (RAG)').first().json.trilha_conhecimento || []; } catch (e) { return []; } })(),
  memoria_considerada: (function(){ try { return $('Agente de Memória (Feedback)').first().json.memoria_itens || []; } catch (e) { return []; } })(),
  oportunidade_total_min, oportunidade_total_max
};

